def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    my_def = 0
    for me, opp in history:
        if opp == 'D':
            opp_def += 1
        if me == 'D':
            my_def += 1

    if n >= 2 and opp_def >= n * 0.8:
        return 'D'

    last_me, last_opp = history[-1]

    if opp_def > 0:
        if last_opp == 'D':
            if last_me == 'D':
                return 'C'
            else:
                if n >= 2 and history[-2][0] == 'D':
                    return 'C'
                return 'D'
        else:
            return 'C'
    else:
        if my_def == 0:
            if n >= 70:
                return 'D'
            return 'C'
        else:
            if my_def == 1 and last_me == 'D':
                return 'C'
            return 'D'
